 static List<ItemStack> rare(ServerPlayer p)throws Exception{var r=Class.forName("io.redspace.ironsspellbooks.api.registry.SpellRegistry");var t=Class.forName("io.redspace.ironsspellbooks.api.spells.AbstractSpell");var rarity=Class.forName("io.redspace.ironsspellbooks.api.spells.SpellRarity");var result=new ArrayList<ItemStack>();var ids=new HashSet<String>();for(var spell:(List<?>)r.getMethod("getEnabledSpells").invoke(null)){int level=(Integer)t.getMethod("getMinLevelForRarity",rarity).invoke(spell,rarity.getField("RARE").get(null));if(level<1||level>(Integer)t.getMethod("getMaxLevel").invoke(spell))continue;var item=new ItemStack(BuiltInRegistries.ITEM.get(ResourceLocation.parse("irons_spellbooks:scroll")));Class.forName("io.redspace.ironsspellbooks.api.spells.ISpellContainer").getMethod("createScrollContainer",t,int.class,ItemStack.class).invoke(null,spell,level,item);var fact=NativeLibraryScroll.inspect(p,item);if(fact!=null&&ids.add(fact.spell()))result.add(item);if(result.size()==6)break;}return result;}
